			"Access.ImportExportSpecification": {"displayName":"ImportExportSpecification","members":[{"name":"Application","kind":"property","returns":"Access.Application","declaredType":"Application","access":"read-only","doc":{"summary":"Use the Application property to access the active Microsoft Access Application object and its related properties. Read-only Application object.","params":[],"source":"external"}},{"name":"Delete","kind":"method","signature":"Delete()","doc":{"summary":"Deletes the specified ImportExportSpecification object from the ImportExportSpecifications collection.","params":[],"source":"external"}},{"name":"Description","kind":"property","declaredType":"String","access":"read/write","doc":{"summary":"Gets or sets a String that describes the specified ImportExportSpecification object. Read/write.","params":[],"source":"external"}},{"name":"Execute","kind":"method","signature":"Execute([Prompt As Variant])","doc":{"summary":"Executes the specified import or export specification.","params":[{"name":"Prompt","text":"","type":"Variant"}],"source":"external"}},{"name":"Name","kind":"property","declaredType":"String","access":"read/write","doc":{"summary":"Gets or sets the name of the specified ImportExportSpecification object. Read/write String.","params":[],"source":"external"}},{"name":"Parent","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Returns the parent object for the specified object. Read-only Object.","params":[],"source":"external"}},{"name":"XML","kind":"property","declaredType":"String","access":"read/write","doc":{"summary":"Gets or sets the Extensible Markup Language (XML) string that defines an ImportExportSpecification object. Read/write String.","params":[],"source":"external"}}],"doc":{"summary":"Represents a saved import or export operation.","remarks":"An ImportExportSpecification object contains all the information that Microsoft Access needs to repeat an import or export operation without your having to provide any input. For example, an import specification that imports data from a Microsoft Office Excel 2007 workbook stores the name of the source Excel file, the name of the destination database, and other details, such as whether you appended to or created a new table, primary key information, field names, and so on. Use the Add method of the ImportExportSpecifications collection to create a new ImportExportSpecification object. Use the…","params":[],"source":"external"}},
			"Access.ImportExportSpecifications": {"displayName":"ImportExportSpecifications","members":[{"name":"Add","kind":"method","returns":"Access.ImportExportSpecification","signature":"Add(Name As String, SpecificationDefinition As String) As ImportExportSpecification","doc":{"summary":"Adds a new ImportExportSpecification object to the ImportExportSpecifications collection.","params":[{"name":"Name","text":"The name to use for the ImportExportSpecification.","type":"String"},{"name":"SpecificationDefinition","text":"The XML markup that represents the settings to save for the import or export operation.","type":"String"}],"source":"external"}},{"name":"Application","kind":"property","returns":"Access.Application","declaredType":"Application","access":"read-only","doc":{"summary":"Use the Application property to access the active Microsoft Access Application object and its related properties. Read-only Application object.","params":[],"source":"external"}},{"name":"Count","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Use the Count property to determine the number of items in a specified collection. Read-only Long.","params":[],"source":"external"}},{"name":"Item","kind":"property","returns":"Access.ImportExportSpecification","declaredType":"ImportExportSpecification","access":"read-only","doc":{"summary":"The Item property returns a specific member of a collection either by position or by index. Read-only ImportExportSpecification.","params":[],"source":"external"}},{"name":"Parent","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Returns the parent object for the specified object. Read-only Object.","params":[],"source":"external"}}],"doc":{"summary":"Represents the collection of available ImportExportSpecification objects.","remarks":"Use the Add method to create a new ImportExportSpecification object. Use the ImportExportSpecification property of the CodeProject or CurrentProject object to return the ImportExportSpecifications collection.","params":[],"source":"external"}},
